var live = (data && data.length) ? data[0] : {};
function rerender(){try{if(ctx.$scope&&ctx.$scope.markdownWidget&&ctx.$scope.markdownWidget.onDataUpdated){ctx.$scope.markdownWidget.onDataUpdated();return;}}catch(e){} try{ctx.detectChanges&&ctx.detectChanges();}catch(e){}}
function fixedWindow(){var tw=null; try{tw=ctx.dashboardTimewindow||(ctx.dashboard&&ctx.dashboard.dashboardTimewindow);}catch(e){}
  if(tw&&tw.history&&tw.selectedTab===1){var h=tw.history; if(h.fixedTimewindow&&(h.historyType===1||h.historyType===undefined)) return {start:h.fixedTimewindow.startTimeMs,end:h.fixedTimewindow.endTimeMs};}
  return null;}
if(!ctx.__bsTwSub){ctx.__bsTwSub=true; try{var ob=ctx.dashboard&&ctx.dashboard.dashboardTimewindowChanged; if(ob&&ob.subscribe){ob.subscribe(function(){setTimeout(rerender,0);});}}catch(e){}}
var win=fixedWindow(); var d=live; var windowTs=null;
if(win){
  var ck=win.start+'-'+win.end; var c=ctx.__bsCache;
  if(!c||c.key!==ck){
    ctx.__bsCache={key:ck,loading:true};
    var id=(ctx.datasources&&ctx.datasources[0]&&ctx.datasources[0].entityId)||'459bf160-73a2-11f1-9bdd-5306fbac003e';
    var url='/api/plugins/telemetry/DEVICE/'+id+'/values/timeseries?keys='+KEYS.join(',')+'&startTs='+win.start+'&endTs='+win.end+'&limit=1&agg=NONE&orderBy=DESC&useStrictDataTypes=false';
    try{ctx.http.get(url).subscribe(function(res){var o={},last=0; for(var k in res){if(res[k]&&res[k].length){o[k]=res[k][0].value; if(res[k][0].ts>last) last=res[k][0].ts;}} ctx.__bsCache={key:ck,data:o,ts:last}; rerender();},
                                    function(){ctx.__bsCache={key:ck,failed:true}; rerender();});}
    catch(e){ctx.__bsCache={key:ck,failed:true};}
    c=ctx.__bsCache;
  }
  if(c.loading) return '<div class="loading">Caricamento dei dati del periodo…</div>';
  if(c.data){d=c.data; windowTs=c.ts;}
}
function v(k){var x=d[k]; return (x===undefined||x===null||x===''||x==='null'||x==='None')?null:x;}
function n(k){var x=v(k); if(x===null) return null; var f=Number(x); return isNaN(f)?null:f;}
function f(x,dec){return x===null?'—':x.toLocaleString('it-IT',{maximumFractionDigits:dec});}
function ago(ms){if(!ms) return 'n.d.'; var m=Math.round((Date.now()-ms)/60000); if(m<1) return 'adesso'; if(m<60) return m+' min fa'; var h=Math.round(m/60); if(h<48) return h+' h fa'; return Math.round(h/24)+' giorni fa';}
function tile(cls,lbl,val,unit,sub){return '<div class="tile '+cls+'"><div class="lbl">'+lbl+'</div><div class="val">'+val+(unit&&val!=='—'?'<span class="unit">'+unit+'</span>':'')+'</div><div class="sub">'+(sub||'&nbsp;')+'</div></div>';}

var stages={no_growth:'Nessuna crescita',spore_or_swelling:'Spore',early_germination:'Germinazione',hyphal_growth:'Crescita ife',mycelial_network:'Rete miceliale'};
var risk=v('risk_level'); var rcls={basso:'r-basso',medio:'r-medio',alto:'r-alto',critico:'r-critico'}[risk]||'';
var riskTxt=risk?risk.charAt(0).toUpperCase()+risk.slice(1):'—';
var st=v('growth_stage'); var stTxt=st?(stages[st]||st):'—';
var conf=v('stage_confirmed'); var inVer=(conf===false||conf==='false');
var germ=n('cumulative_germination_percent'); var gtc=n('germinated_track_count'); var tsc=n('tracked_spore_count');
var ttg=n('avg_time_to_germination_s'); var obs=n('germination_observed_count');
var act=v('active'); var online=(act===true||act==='true'); var last=n('lastActivityTime');
var h='<div class="tiles n5">';
h+=tile(rcls,'Livello di rischio',riskTxt,'','basato sullo stadio confermato');
h+=tile('ok','Stadio di crescita',stTxt,'',inVer?'<span class="badge">nuovo stadio in verifica</span>':'confermato su più scatti');
h+=tile('ok','Germinazione',f(germ,1),'%',(gtc!==null&&tsc!==null)?(f(gtc,0)+' spore su '+f(tsc,0)):'');
h+=tile('ok','Tempo medio di germinazione',ttg===null?'—':f(ttg/3600,1),'h',obs!==null?('calcolato su '+f(obs,0)+' spore'):'');
if(windowTs){var dt=new Date(windowTs); h+=tile('ok','Dati del periodo',dt.toLocaleDateString('it-IT',{day:'2-digit',month:'short'}),'','ultimo scatto alle '+dt.toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'}));}else{h+=tile(online?'ok':'crit','Sensore',online?'Online':'Offline','','ultimo dato: '+ago(last));}
h+='</div>';
return h;

